require_once __DIR__.'/../config.php';require_once __DIR__.'/lib/Portal.php';require_once __DIR__.'/lib/Layout.php';$ctx=rxp_context($pdo);$owner=rxp_target_reseller($ctx);$dir=rxp_bot_dir($pdo,$owner);$flash='';$ft='ok';$file=$dir?$dir.'/text.json':'';$d=($file&&is_file($file))?(json_decode((string)file_get_contents($file),true)?:[]):[];$d['btn_keyboard']=$d['btn_keyboard']??[];$d['text_account']=$d['text_account']??[];$d['brand']=$d['brand']??[];if(($_SERVER['REQUEST_METHOD']??'')==='POST'){if(!$dir)rxp_abort(409,'ربات اختصاصی وجود ندارد.');foreach(['buy','test','my_service','wallet','support'] as $k)$d['btn_keyboard'][$k]=mb_substr(trim((string)($_POST['btn_'.$k]??'')),0,64);$d['text_account']['add_balance']=mb_substr(trim((string)($_POST['add_balance']??'')),0,1000);$d['brand']['name']=mb_substr(trim((string)($_POST['brand_name']??'')),0,100);$d['brand']['start_message']=mb_substr(trim((string)($_POST['start_message']??'')),0,2000);$d['brand']['support_link']=mb_substr(trim((string)($_POST['support_link']??'')),0,200);file_put_contents($file,json_encode($d,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT),LOCK_EX);rxp_audit($pdo,$ctx,'branding.update',$owner);$flash='متن‌ها و برند ذخیره شد.';}rxp_layout_start($ctx,'برند و متن‌ها','branding.php');rxp_flash($flash,$ft);?>
<h1 class="rxp-title">برند و متن‌های ربات</h1><?php if($ctx['role']==='super'):?><div class="rxp-card"><form method="get"><select name="owner" onchange="this.form.submit()"><?php foreach($ctx['scope_ids'] as $id):?><option value="<?=$id?>" <?=$owner===$id?'selected':''?>>نماینده #<?=$id?></option><?php endforeach;?></select></form></div><?php endif;?><?php if(!$dir):?><div class="rxp-flash err">ربات اختصاصی وجود ندارد.</div><?php else:?><form method="post"><input type="hidden" name="owner" value="<?=rxp_h($owner)?>"><div class="rxp-card"><h2>هویت برند</h2><div class="rxp-field"><label>نام برند</label><input name="brand_name" value="<?=rxp_h($d['brand']['name']??'')?>" style="width:100%"></div><div class="rxp-field"><label>پیام شروع</label><textarea name="start_message" style="width:100%;min-height:100px"><?=rxp_h($d['brand']['start_message']??'')?></textarea></div><div class="rxp-field"><label>لینک پشتیبانی</label><input name="support_link" value="<?=rxp_h($d['brand']['support_link']??'')?>" style="width:100%"></div></div><div class="rxp-card"><h2>دکمه‌ها</h2><div class="rxp-grid"><?php foreach(['buy'=>'خرید','test'=>'تست','my_service'=>'سرویس‌های من','wallet'=>'کیف پول','support'=>'پشتیبانی'] as $k=>$l):?><div class="rxp-field"><label><?=$l?></label><input name="btn_<?=$k?>" value="<?=rxp_h($d['btn_keyboard'][$k]??'')?>"></div><?php endforeach;?></div><div class="rxp-field"><label>متن شارژ کیف پول</label><textarea name="add_balance" style="width:100%"><?=rxp_h($d['text_account']['add_balance']??'')?></textarea></div><button class="rxp-btn">ذخیره</button></div></form><?php endif;?><?php rxp_layout_end();
